<?php
declare(strict_types=1);

/**
 * install_standings_timeline_lite_visual_alignment.php
 *
 * VERSION: v001
 * LAST MODIFIED: 8/28/2026 1:01:11 am
 *
 * PURPOSE:
 * Controlled two-file presentation migration:
 *   1) weekly_standings.php v066 -> v067
 *   2) standings_timeline_lite.php v002 -> v003
 *
 * SCOPE:
 * - Align timeline-lite presentation with weekly_standings.php.
 * - Add subdued "Standings as of ..." pill and AUTO-SCORING – UNOFFICIAL pill.
 * - Match four-table sizing/styling.
 * - Widen the shared score column to 64px in both pages so Week 25+ fits.
 *
 * SAFETY:
 * - exact SHA-256 baseline checks for both files
 * - confirms standings_timeline.php dependency exists
 * - records dependency hash before writes and verifies it is unchanged after writes
 * - backs up BOTH target files before replacing either
 * - complete-file replacements only
 * - all-or-nothing rollback if a write/postflight check fails
 * - no DB, snapshot, scoring, timeline engine, helper, release-history, or export files are changed
 */

date_default_timezone_set('America/New_York');

const WEEKLY_BASE_SHA256 = '385386001e8968c9c4c37a3ea2bbc66842e42eda9fe5b801f1c7e3994fd6deaf';
const LITE_BASE_SHA256 = '76f9c73fced88d6c83de5a4b8ec4c806e537e29a470b44708ea18d3d2d259f37';
const TIMELINE_REFERENCE_SHA256 = 'b3671fae0998576b36055b05e747129a392e173e82b9048a73d05dec4b0b4a2e';
const WEEKLY_NEW_SHA256 = '8c9d728af5f3cba290ba0cd652e06542edc4ebabc62d2851b9336f3352d29217';
const LITE_NEW_SHA256 = 'f098222464c933f7e94d5540b4d75f8755defe919ccab777c04b6eded326752e';

$weeklyPath = __DIR__ . '/weekly_standings.php';
$litePath = __DIR__ . '/standings_timeline_lite.php';
$timelinePath = __DIR__ . '/standings_timeline.php';

$weeklyReplacement = base64_decode('', true);
$liteReplacement = base64_decode('', true);

function ih(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

function preflight_row(string $label, bool $ok, string $detail = ''): void
{
    echo '<tr><td>' . ih($label) . '</td><td class="' . ($ok ? 'ok' : 'bad') . '">' . ($ok ? 'PASS' : 'FAIL') . '</td><td>' . ih($detail) . '</td></tr>';
}

function atomic_write_file(string $path, string $data): bool
{
    $tmp = $path . '.tmp_' . bin2hex(random_bytes(4));
    if (file_put_contents($tmp, $data, LOCK_EX) === false) {
        return false;
    }
    if (!@rename($tmp, $path)) {
        @unlink($tmp);
        return false;
    }
    return true;
}

$weeklyExists = is_file($weeklyPath);
$liteExists = is_file($litePath);
$timelineExists = is_file($timelinePath);

$weeklyCurrentHash = $weeklyExists ? (string)hash_file('sha256', $weeklyPath) : '';
$liteCurrentHash = $liteExists ? (string)hash_file('sha256', $litePath) : '';
$timelineBeforeHash = $timelineExists ? (string)hash_file('sha256', $timelinePath) : '';

$weeklyBaselineOk =
    $weeklyExists
    && $weeklyCurrentHash === WEEKLY_BASE_SHA256
    && strpos((string)file_get_contents($weeklyPath), 'VERSION: v066') !== false;

$liteBaselineOk =
    $liteExists
    && $liteCurrentHash === LITE_BASE_SHA256
    && strpos((string)file_get_contents($litePath), 'VERSION: v002') !== false;

$timelineReferenceOk =
    $timelineExists
    && strpos((string)file_get_contents($timelinePath), 'standings_timeline.php') !== false;

$weeklyReplacementOk =
    is_string($weeklyReplacement)
    && hash('sha256', $weeklyReplacement) === WEEKLY_NEW_SHA256
    && strpos($weeklyReplacement, 'VERSION: v067') !== false
    && strpos($weeklyReplacement, 'width: 64px;') !== false
    && strpos($weeklyReplacement, 'AUTO-SCORING – UNOFFICIAL') !== false;

$liteReplacementOk =
    is_string($liteReplacement)
    && hash('sha256', $liteReplacement) === LITE_NEW_SHA256
    && strpos($liteReplacement, 'VERSION: v003') !== false
    && strpos($liteReplacement, "\$topBannerText = 'Standings as of '") !== false
    && strpos($liteReplacement, 'class="unofficial-status-pill"') !== false
    && strpos($liteReplacement, 'width: 64px;') !== false;

$preflightOk = $weeklyBaselineOk && $liteBaselineOk && $timelineReferenceOk && $weeklyReplacementOk && $liteReplacementOk;
$apply = isset($_POST['apply']) && $_POST['apply'] === '1';

$messages = [];
$success = false;

if ($apply && $preflightOk) {
    $backupDir = __DIR__ . '/_migration_backups/standings_timeline_lite_visual_alignment_' . date('Ymd_His');
    $ok = is_dir($backupDir) || mkdir($backupDir, 0755, true);

    if (!$ok) {
        $messages[] = 'FAIL: Could not create backup directory.';
    }

    if ($ok && !copy($weeklyPath, $backupDir . '/weekly_standings.php')) {
        $ok = false;
        $messages[] = 'FAIL: Could not back up weekly_standings.php v066.';
    } elseif ($ok) {
        $messages[] = 'PASS: Backed up weekly_standings.php v066.';
    }

    if ($ok && !copy($litePath, $backupDir . '/standings_timeline_lite.php')) {
        $ok = false;
        $messages[] = 'FAIL: Could not back up standings_timeline_lite.php v002.';
    } elseif ($ok) {
        $messages[] = 'PASS: Backed up standings_timeline_lite.php v002.';
    }

    if ($ok && !atomic_write_file($weeklyPath, $weeklyReplacement)) {
        $ok = false;
        $messages[] = 'FAIL: Could not install weekly_standings.php v067.';
    } elseif ($ok) {
        $messages[] = 'PASS: Installed weekly_standings.php v067.';
    }

    if ($ok && !atomic_write_file($litePath, $liteReplacement)) {
        $ok = false;
        $messages[] = 'FAIL: Could not install standings_timeline_lite.php v003.';
    } elseif ($ok) {
        $messages[] = 'PASS: Installed standings_timeline_lite.php v003.';
    }

    if ($ok) {
        $weeklyInstalled = (string)file_get_contents($weeklyPath);
        $liteInstalled = (string)file_get_contents($litePath);
        $timelineAfterHash = is_file($timelinePath) ? (string)hash_file('sha256', $timelinePath) : '';

        $checks = [
            'weekly_standings v067 header' => strpos($weeklyInstalled, 'VERSION: v067') !== false,
            'weekly shared score width = 64px' => strpos($weeklyInstalled, '.col-score') !== false && strpos($weeklyInstalled, 'width: 64px;') !== false,
            'weekly existing unofficial pill retained' => strpos($weeklyInstalled, 'AUTO-SCORING – UNOFFICIAL') !== false,
            'weekly replacement hash exact' => hash_file('sha256', $weeklyPath) === WEEKLY_NEW_SHA256,

            'timeline-lite v003 header' => strpos($liteInstalled, 'VERSION: v003') !== false,
            'timeline-lite subdued as-of text' => strpos($liteInstalled, "\$topBannerText = 'Standings as of '") !== false,
            'timeline-lite unofficial screen pill' => strpos($liteInstalled, 'class="unofficial-status-pill"') !== false,
            'timeline-lite unofficial print marker' => strpos($liteInstalled, 'class="unofficial-print-marker"') !== false,
            'timeline-lite shared score width = 64px' => strpos($liteInstalled, 'width: 64px;') !== false,
            'timeline-lite 1400px page width' => strpos($liteInstalled, 'max-width: 1400px;') !== false,
            'timeline-lite replacement hash exact' => hash_file('sha256', $litePath) === LITE_NEW_SHA256,

            'standings_timeline.php dependency untouched' => $timelineBeforeHash !== '' && $timelineAfterHash === $timelineBeforeHash,
        ];

        foreach ($checks as $label => $pass) {
            $messages[] = ($pass ? 'PASS: ' : 'FAIL: ') . $label;
            if (!$pass) {
                $ok = false;
            }
        }
    }

    if (!$ok) {
        $restoreWeekly = is_file($backupDir . '/weekly_standings.php')
            ? copy($backupDir . '/weekly_standings.php', $weeklyPath)
            : false;
        $restoreLite = is_file($backupDir . '/standings_timeline_lite.php')
            ? copy($backupDir . '/standings_timeline_lite.php', $litePath)
            : false;

        $messages[] = $restoreWeekly
            ? 'ROLLBACK: Restored weekly_standings.php v066.'
            : 'ROLLBACK ERROR: Could not restore weekly_standings.php v066.';
        $messages[] = $restoreLite
            ? 'ROLLBACK: Restored standings_timeline_lite.php v002.'
            : 'ROLLBACK ERROR: Could not restore standings_timeline_lite.php v002.';
    } else {
        $success = true;
    }
}
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>MRL Timeline Lite Visual Alignment</title>
<style>
* { box-sizing: border-box; }
html { background: #111; }
body { margin: 0; color: #eee; font-family: Tahoma, Verdana, "Segoe UI", sans-serif; }
.wrap { width: 94%; max-width: 1120px; margin: 20px auto; }
.card { background: #202020; border: 1px solid #555; border-radius: 14px; padding: 20px; margin-bottom: 16px; }
